def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """

    def decorator(func):
        cache = OrderedDict()
        usage_count = {}

        def wrapper(*args):
            key = (args, args) if typed else args
            if key not in cache:
                cache[key] = func(*args)
                usage_count[key] = 1
            else:
                usage_count[key] += 1

            # Remove the least frequently used item
            while len(cache) > maxsize:
                least_used_key = next(iter(cache))
                if usage_count[least_used_key] == 1:
                    del usage_count[least_used_key]
                del cache[least_used_key]

            return cache[key]

        return wrapper

    return decorator

