class ExceptionToString:
    @classmethod
    def extostr(cls, e, max_level=30, max_path_level=5):
        """
        Format an exception.
        :param e: Any exception instance.
        :type e: Exception
        :param max_level: Maximum call stack level (default 30)
        :type max_level: int
        :param max_path_level: Maximum path level (default 5)
        :type max_path_level: int
        :return The exception readable string
        :rtype str
        """
        if not isinstance(e, Exception):
            raise ValueError("The first argument must be an exception instance.")

        def get_stack(tb, level):
            stack = []
            while tb and level > 0:
                stack.append((tb.tb_frame.f_code.co_filename, tb.tb_frame.f_code.co_name, tb.tb_lineno))
                tb = tb.tb_next
                level -= 1
            return stack

        def format_tb(stack):
            tb_str = []
            for filename, name, line in stack:
                tb_str.append(f"  File \"{filename}\", line {line}, in {name}")
            return "\n".join(tb_str)

        def get_path(stack):
            path = []
            filename = stack[0][0]
            for item in stack:
                if item[0] != filename:
                    filename = item[0]
                    path.append(filename)
                if len(path) >= max_path_level:
                    break
            return "\n".join(path)

        def format_exception(e):
            return f"{e.__class__.__name__}: {str(e)}"

        stack = get_stack(e.__traceback__, max_level)
        tb_str = format_tb(stack)
        path_str = get_path(stack)
        exception_str = format_exception(e)

        return f"{exception_str}\n{tb_str}\nPath:\n{path_str}"
