def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    def is_subclass_of(other, base):
        return issubclass(other, base) and not issubclass(base, other)

    bases = list(classes)
    reduced = []

    while bases:
        current = bases.pop(0)
        if all(is_subclass_of(class_, current) for class_ in bases):
            reduced.append(current)

    return reduced
