def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not classes:
        return []

    # Create a dictionary to store the inheritance relationships
    inheritance = {cls: [] for cls in classes}

    # Populate the inheritance dictionary
    for cls in classes:
        for base in cls.__bases__:
            if base in classes:
                inheritance[cls].append(base)

    # Find the minimum equivalent classes
    visited = set()
    result = []

    def dfs(cls):
        if cls not in visited:
            visited.add(cls)
            for base in inheritance[cls]:
                dfs(base)
            result.append(cls)

    for cls in classes:
        if cls not in visited:
            dfs(cls)

    return result[::-1]
