from functools import lru_cache

@lru_cache(None)
def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not classes:
        return []

    # Create a dictionary to store the class hierarchy
    hierarchy = {cls: set(cls.__bases__) for cls in classes}

    # Find all classes that are not bases of any other class
    non_bases = set([cls for cls in hierarchy if not any(hierarchy[child].issuperset({cls}) for child in hierarchy)])

    # Remove non-base classes from the hierarchy
    reduced_hierarchy = {cls: bases - non_bases for cls, bases in hierarchy.items()}

    # Find the minimum equivalent base classes
    min_bases = set([cls for cls in classes if all(not reduced_hierarchy[child].intersection({cls}) for child in hierarchy[child])])

    # Return the ordered minimum equivalent base classes
    return sorted(min_bases, key=lambda x: classes.index(x))
