def format(
    self,
    sql: AnyStr,
    params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    if isinstance(params, dict):
        # Convert named parameters to question marks for execution
        placeholders = [f"%({key})s" for key in params]
        formatted_sql = sql % tuple(placeholders)
        out_params = {i: value for i, value in enumerate(params.values(), start=1)}
    elif isinstance(params, Sequence):
        # Convert ordinal parameters to question marks for execution
        placeholders = ["%s"] * len(params)
        formatted_sql = sql % tuple(placeholders)
        out_params = list(params)
    else:
        raise ValueError("params must be a Mapping or Sequence")

    return formatted_sql, out_params
