def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.

    """
    def decorator(func):
        if hasattr(self, 'handlers'):
            self.handlers[hook].append(func)
        else:
            self.handlers = {hook: [func]}
        return func
    return decorator

def on(hook: HookType) -> Callable[[Any], Any]:
    def decorator(listener: Any) -> Any:
        # Assuming a global registry to hold hooks and listeners
        if hook not in registry:
            registry[hook] = []
        registry[hook].append(listener)
        return listener
    return decorator

