import os
from pathlib import Path
from typing import Optional, Union

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[Path, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    if not os.path.exists(tmp_path):
        os.makedirs(tmp_path)

    if not filename:
        filename = os.path.basename(archive_path)

    extract_path = os.path.join(tmp_path, os.path.splitext(filename)[0])
    if not os.path.exists(extract_path):
        os.makedirs(extract_path)

    if archive_path.endswith('.zip'):
        subprocess.call(['unzip', archive_path, '-d', extract_path])
    elif archive_path.endswith('.tar.gz'):
        subprocess.call(['tar', '-xzf', archive_path, '-C', extract_path])
    elif archive_path.endswith('.tar.bz2'):
        subprocess.call(['tar', '-xjf', archive_path, '-C', extract_path])
    else:
        raise ValueError("Unsupported archive format")

    return extract_path
