                config_results[filename] = config_data
        except FileNotFoundError as e:
            log_record = logging.LogRecord(level=logging.ERROR, name=logger.name, msg=f"Configuration file not found: {filename}", args=(), exc_info=None)
            log_records.append(log_record)
        except json.JSONDecodeError as e:
            log_record = logging.LogRecord(level=logging.ERROR, name=logger.name, msg=f"Failed to decode JSON in configuration file: {filename}", args=(e,), exc_info=None)
            log_records.append(log_record)
        except Exception as e:
            log_record = logging.LogRecord(level=logging.ERROR, name=logger.name, msg=f"Unexpected error loading configuration file: {filename}", args=(e,), exc_info=None)
            log_records.append(log_record)

