def verifyObject(iface, candidate, tentative=False):
    if not tentative and not iface.providedBy(candidate):
        raise Invalid(f"Requested interface {iface} not provided by candidate")

    object_interface_names = getInterfaceNames(candidate.__class__)
    if iface.__identifier__ not in object_interface_names:
        raise Invalid(f"Requested interface {iface} not provided by candidate class")

    candidate_methods = set(dir(candidate))
    required_methods = set(iface.names())
    for method in required_methods:
        if method not in candidate_methods:
            raise Invalid(f"Missing method {method} in candidate")

        cand_method = getattr(candidate, method)
        req_method = getattr(iface, method)
        if not callable(cand_method) or not callable(req_method):
            raise Invalid(f"Method {method} is not callable in candidate")

        cand_params = set(cand_method.__code__.co_varnames)
        req_params = set(req_method.__code__.co_varnames)
        if cand_params != req_params:
            raise Invalid(f"Mismatch in parameters for method {method}")

    candidateAttributes = set(candidate.__dict__.keys())
    requiredAttributes = set([name for name in dir(iface) if not name.startswith('__')])
    for attribute in requiredAttributes:
        if attribute not in candidateAttributes:
            raise Invalid(f"Missing attribute {attribute} in candidate")

    return True
