import re
from datetime import datetime, timedelta
from dateutil.tz import tzoffset, tzutc

class DateFormatter:
    def __init__(self):
        self.date_regex = re.compile(r"""
            ^(?P<year>\d{4})$
            |^(?P<year>\d{4})(?P<month>\d{2})$
            |^(?P<year>\d{4})(?P<month>\d{2})(?P<day>\d{2})$
            """, re.VERBOSE)

        self.time_regex = re.compile(r"""
            ^(?P<hour>\d{2})$
            |^(?P<hour>\d{2}):(?P<minute>\d{2})$
            |^(?P<hour>\d{2}):(?P<minute>\d{2}):(?P<second>\d{2})$
            |^(?P<hour>\d{2}):(?P<minute>\d{2}):(?P<second>\d{2}\.\d{1,6})$
            """, re.VERBOSE)

        self.week_regex = re.compile(r"""
            ^(?P<year>\d{4})-W(?P<week>\d{2})$
            |^(?P<year>\d{4})-W(?P<week>\d{2})(?P<day>\d{1})$
            """, re.VERBOSE)

    def _apply_timezones(self, dt, tz_str):
        if tz_str == 'Z':
            return dt.replace(tzinfo=tzutc())
        elif tz_str:
            hours, minutes = map(int, tz_str.split(':'))
            return dt.replace(tzinfo=tzoffset(None, hours * 3600 + minutes * 60))
        else:
            return dt

    def _parse_date(self, date_str):
        match = self.date_regex.match(date_str)
        if match:
            year = int(match.group('year'))
            month = int(match.group('month')) if match.group('month') else 1
            day = int(match.group('day')) if match.group('day') else 1
            return datetime(year, month, day)
        else:
            match = self.week_regex.match(date_str)
            if match:
                year = int(match.group('year'))
                week = int(match.group('week'))
                day = int(match.group('day')) if match.group('day') else 1
                date = datetime.strptime(f'{year}-W{week}', '%Y-W%U') + timedelta(days=day-1)
                return date.replace(hour=0, minute=0, second=0, microsecond=0)
            else:
                raise ValueError("Invalid date format")

    def _parse_time(self, time_str):
        match = self.time_regex.match(time_str)
        if match:
            hour = int(match.group('hour')) % 24
            minute = int(match.group('minute')) if match.group('minute') else 0
            second = float(match.group('second')) if match.group('second') else 0
            microsecond = int((second - int(second)) * 1e6)
            if hour == 24:
                hour = 0
            return datetime.combine(datetime(1, 1, 1), datetime.time(datetime(1, 1, 1, hour, minute, int(second), microsecond)))
        else:
            raise ValueError("Invalid time format")

    @_takes_ascii
    def isoparse(self, dt_str):
        dt_parts = dt_str.split('T' if 'T' in dt_str else ' ')
        date_part = dt_parts[0]
        time_part = dt_parts[1] if len(dt_parts) > 1 else ''
        tz_part = dt_parts[2] if len(dt_parts) > 2 else ''

        date = self._parse_date(date_part)
        time = self._parse_time(time_part)
        dt = date.replace(hour=time.hour, minute=time.minute, second=time.second, microsecond=time.microsecond)

        return self._apply_timezones(dt, tz_part)
